// Fill NON-SECRET values only. Bind an n8n Header Auth credential to BOTH HTTP Request nodes.
// No provider token or phone number may be put in this Code node / JSON export.
const config={
  chatwootUrl:'https://REPLACE_CHATWOOT_HOST',
  chatwootAccountId:'REPLACE_ACCOUNT_ID',
  chatwootCampaignId:'REPLACE_CAMPAIGN_DISPLAY_ID',
  maximumPages:500,
};
if(Object.values(config).some(v=>typeof v==='string'&&v.includes('REPLACE_')))throw new Error('READ_ONLY_SETUP_REQUIRED: fill non-secret Chatwoot host/account/campaign ID');
const host=new URL(config.chatwootUrl);
if(host.protocol!=='https:')throw new Error('Remote Chatwoot must use HTTPS');
for(const name of ['chatwootAccountId','chatwootCampaignId']){
 if(!/^[1-9][0-9]*$/.test(String(config[name])))throw new Error('Invalid '+name);
}
return [{json:config}];

const page=$input.first().json;
const limit=$('Configure Read-only Chatwoot').first().json.maximumPages;
const count=page?.meta?.total_count;
const total=page?.meta?.total_pages;
if(!Number.isInteger(count)||count<0||!Number.isInteger(total)||total<0||total>limit)throw new Error('Bad Chatwoot analytics metadata or page count exceeds safe limit');
if(total===0&&(count!==0||page?.payload?.length!==0))throw new Error('Contradictory zero-page analytics response');
if(total>0&&page.meta.current_page!==1)throw new Error('Incorrect first-page index');
return Array.from({length:Math.max(total,1)},(_,i)=>({json:{page:i+1}}));

// Output only aggregate information: individual contacts, phone numbers, and message bodies
// are deliberately not emitted from the workflow. No CRM/Chatwoot writes.
const metrics=$('GET Campaign Metrics').first().json;
const pages=$input.all().map(i=>i.json);
const byPage=new Map();
for(const page of pages){
 const pageNo=page?.meta?.current_page;
 if(!Number.isInteger(pageNo)||byPage.has(pageNo)||!Array.isArray(page.payload))throw new Error('Duplicate/invalid recipient page');
 byPage.set(pageNo,page);
}
const first=byPage.get(1),total=first?.meta?.total_pages,count=first?.meta?.total_count;
if(!Number.isInteger(total)||total<0||!Number.isInteger(count)||count<0||pages.length!==Math.max(1,total))throw new Error('Incomplete recipient pagination');
if(total===0&&count!==0)throw new Error('Inconsistent zero-recipient metadata');
const counts={queued:0,skipped:0,sent:0,delivered:0,read:0,failed:0};
const codes={},seen=new Set();
for(let k=1;k<=Math.max(1,total);k++){
 const p=byPage.get(k);
 if(!p||p.meta.total_pages!==total||p.meta.total_count!==count)throw new Error('Metadata drift during pagination');
 for(const row of p.payload){
  const cid=row?.contact?.id,status=row?.status;
  if(!Number.isInteger(cid)||seen.has(cid)||!Object.hasOwn(counts,status))throw new Error('Invalid/duplicated recipient state');
  seen.add(cid);counts[status]++;
  if(status==='failed') {const code=row.error_code===null||row.error_code===undefined?'UNKNOWN':String(row.error_code);codes[code]=(codes[code]??0)+1;}
 }
}
if(seen.size!==count||metrics.audience!==count||metrics.delivered!==counts.delivered+counts.read||metrics.read!==counts.read||metrics.failed!==counts.failed||metrics.skipped!==counts.skipped)throw new Error('Contacts/metrics mismatch');
return [{json:{checkedAt:new Date().toISOString(),mode:'READ_ONLY',chatwootCampaignDisplayId:Number($('Configure Read-only Chatwoot').first().json.chatwootCampaignId),pagesFetched:pages.length,audience:count,counts,deliveredInclusiveOfRead:counts.delivered+counts.read,errorCodeCounts:codes,individualResultsObserved:count,crmEventWriteAuthorized:false,reason:'No verified Meta message IDs/event timestamps from this endpoint'}}];
